import json
try:
    json.dumps({'_id': object()})
except TypeError:
    print('not serializable')

db = [{'id': 1, 'name': 'Ada', 'city': 'London'}]
def put(student_id, new):
    for i, s in enumerate(db):
        if s['id'] == student_id:
            db[i] = {'id': student_id, **new}
put(1, {'name': 'Ada', 'city': 'Paris'})
print(db)

db = [{'id': 1}, {'id': 2}, {'id': 3}]
def delete(student_id):
    for s in db:
        if s['id'] == student_id:
            db.remove(s)
            break
delete(2)
print(db)

db = {}
def handle(method, key, value=None):
    if method in ('POST', 'PUT'):
        db[key] = value
    elif method == 'DELETE':
        db.pop(key)
    return db.get(key)

print(handle('POST', 1, 'Ada'), handle('PUT', 1, 'Grace'), handle('DELETE', 1))
